js="\nlet hunterData=null,hunterBusy=false,hunterPoll=0,hunterCommandBusy=false;\nconst hunterKnownBTC=h=>['stratum.bitaxe.de','stratum.ckpool.org'].includes(String(h||'').toLowerCase());\nconst hunterFmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString('ru-RU',{maximumFractionDigits:d}):'—';\nfunction hunterRender(){const d=hunterData;const $h=id=>document.getElementById(id);const put=(id,t)=>{$h(id).textContent=t};if(!d){for(const id of ['odday','odmonth','odyear','odevery'])put(id,'—');put('hunterstatus','Нет связи с BTC Hunter. Штатный майнинг не зависит от этого блока.');for(const id of ['hunterstats','hunterodds','huntercandidate','hunterpools','hunterresults','hunterstages','hunterconfidence'])put(id,'—');put('hunterrecommend','Данные недоступны');put('huntertrial','Нет связи с контроллером');$h('hunterstart').disabled=true;$h('hunterstop').disabled=true;return;}\nconst secs=Math.max(0,+d.seconds||0),ps=Array.isArray(d.pools)?d.pools:[],stats=S.pools||[];const sum=(k)=>ps.reduce((a,r)=>a+(Number.isFinite(r[k])?r[k]:0),0),a=sum('accepted'),r=sum('rejected'),h=secs>0?sum('work')*4294967296/secs/1e12:0,ready=secs>=300&&a>=100;\nput('hunterstatus','Автономный учёт · '+hunterFmt(secs/60,0)+' мин с запуска');$h('hunterstats').innerHTML=`<div>Полезная работа</div><div>${ready?hunterFmt(h)+' TH/s':'Накопление'}</div><div>Принято / отклонено (V1)</div><div>${a} / ${r}</div><div>Без ответа / ошибка отправки</div><div>${sum('missing')} / ${sum('failed')}</div><div>Доля отклонённых</div><div>${a+r?hunterFmt(100*r/(a+r),3)+'%':'—'}</div>`;\nconst D=+S.pool?.networkDiff;const btcH=secs>0?sum('btcWork')*4294967296/secs/1e12:0;const allKnown=stats.filter(p=>p.enabled).every(p=>hunterKnownBTC(p.host)&&p.proto<=1);if(ready&&sum('btcAccepted')>=100&&allKnown&&hunterKnownBTC(S.pool?.host)&&D>0&&Number.isFinite(D)&&btcH>0){const odds=sec=>hunterFmt(100*-Math.expm1(-btcH*1e12*sec/(4294967296*D)),9)+'%';put('odday',odds(86400));put('odmonth',odds(2592000));put('odyear',odds(31536000));put('odevery',hunterFmt(4294967296*D/(btcH*1e12*31536000),0)+' лет (среднее)');put('hunterodds','Шанс BTC: сутки '+odds(86400)+' · 30 дней '+odds(2592000)+' · год '+odds(31536000)+'. При неизменных сложности и среднем темпе; не гарантия.')}else{for(const id of ['odday','odmonth','odyear','odevery'])put(id,'—');put('hunterodds','Вероятность: ожидаем достаточную выборку и подтверждённую сеть BTC.');}\nconst c=d.candidate||{},states=['Нет кандидатов','Обнаружен','Отправлен','Принят пулом; наблюдение сети отдельно','Отклонён пулом','Не отправлен / ошибка транспорта','Ответ не получен','Отправлен SV2, индивидуальный ответ неизвестен'];put('huntercandidate','Кандидат: '+(states[c.state]||'Неизвестно')+(c.state?' · пул '+(c.pool+1)+' · '+(c.hash||'')+(c.persisted?'':' · архив не записан'):''));$h('huntercandidate').style.overflowWrap='anywhere';\nconst el=$h('hunterpools');el.textContent='';for(let i=0;i<ps.length;i++){const p=stats[i],m=ps[i];if(!p?.enabled)continue;const item=document.createElement('div');item.style.cssText='padding:10px 0;border-bottom:1px solid var(--line);overflow-wrap:anywhere';const b=document.createElement('b');b.textContent='Слот '+(i+1)+' · текущий адрес: '+(p.host||'—');item.append(b,document.createElement('br'));const note=document.createElement('span');note.textContent=(p.lagBlocks>=3?'Отставание '+p.lagMs+' мс ('+p.lagBlocks+' блоков)':'Недостаточно данных о блоках')+' · доставка '+(m.cleanN?m.cleanMs+' мс, пик '+m.cleanMax+' мс, N='+m.cleanN:'—')+' · V1 принято / отклонено: '+m.accepted+' / '+m.rejected+' · без ответа / ошибка отправки: '+m.missing+' / '+m.failed+' · '+(p.payout===2?'Проверенная выплата '+p.payoutPct+'%; удержание '+hunterFmt(Math.max(0,100-p.payoutPct))+'% (не полный аудит комиссий)':'Выплата и комиссия не подтверждены')+' · соединение: '+(Number.isFinite(m.observedSeconds)?hunterFmt(m.connectedSeconds/60,1)+' мин активно / '+hunterFmt(m.disconnectedSeconds/60,1)+' мин без связи; '+hunterFmt(m.unobservedSeconds/60,1)+' мин без наблюдения':'наблюдения накапливаются');item.append(note);el.append(item)}\nput('hunterrecommend','Оставьте текущий порядок: устойчивого преимущества альтернативы не подтверждено. Накопленные счётчики относятся к слоту с загрузки; после смены адреса они не доказывают историю нового сервера.');\nbenchmarkRender(d);\n\n}\n\nfunction benchmarkRender(d){\n const t=d.trial||{},steps=[500,350,250],order=[500,350,250,250,350,500],put=(id,text)=>$(id).textContent=text;\n const running=t.state===1,stage=Number.isInteger(t.stage)?t.stage:0,phase=t.phase==='warmup'?'Прогрев':t.phase==='measure'?'Измерение':'Этап',duration=t.phase==='warmup'?(t.warmupSeconds||300):(t.measurementSeconds||1800);\n const reasons={none:'причина не указана',user:'отмена пользователем',safety_or_telemetry:'защита или недостоверная телеметрия',pool_changed:'пул изменён',configuration_changed:'настройки изменены',transport_failure:'ошибка отправки',reply_loss_or_rejections:'потеря ответов или рост отказов',cancelled:'отмена пользователем',unstable:'нестабильность режима',insufficient_samples:'недостаточно принятых шар',controller_timeout:'контроллер не отвечает',mode_changed:'режим изменён',temperature_drift:'температура изменилась',connection_lost:'потеря соединения'};\n put('huntertrial',running?'Этап '+(stage+1)+'/'+(t.totalStages||6)+' · '+(t.intervalMs||order[stage]||'—')+' мс · повтор '+(t.round||1)+'/2 · '+phase.toLowerCase()+' '+hunterFmt(t.elapsed/60,1)+' из '+hunterFmt(duration/60,0)+' мин':t.state===2?'Сравнение завершено. Исходный интервал возвращён.':t.state===3?'Сравнение прекращено: '+(reasons[t.abortReason]||t.abortReason||'режим изменён, недостаточно шар или отменено')+'. Исходный интервал возвращён.':'Сравнение не запущено.');\n const container=$('hunterresults');container.textContent='';\n for(let i=0;i<steps.length;i++){\n  const label=document.createElement('div'),value=document.createElement('div');label.textContent=steps[i]+' мс';\n  const count=t.accepted?.[i]||0,reject=t.rejected?.[i]||0,repeats=t.repeatsCompleted?.[i]||0,rate=t.rates?.[i],low=t.ci95Low?.[i],high=t.ci95High?.[i];\n  value.textContent=count>=100&&Number.isFinite(rate)?hunterFmt(rate/1000)+' TH/s · '+count+' / '+reject+' · '+repeats+'/2 повтора'+(Number.isFinite(low)&&Number.isFinite(high)?' · прибл. 95%: '+hunterFmt(low/1000)+'–'+hunterFmt(high/1000)+' TH/s':' · интервал ещё не определён'):'Накопление · '+count+' / '+reject+' · '+repeats+'/2 повтора';\n  container.append(label,value);\n }\n const stages=$('hunterstages');stages.textContent='';for(let i=0;i<order.length;i++){const label=document.createElement('div'),value=document.createElement('div');label.textContent=(i+1)+'. '+order[i]+' мс';const n=t.stageAccepted?.[i]||0;value.textContent=n>=100&&Number.isFinite(t.stageRates?.[i])?hunterFmt(t.stageRates[i]/1000)+' TH/s · '+n+' / '+(t.stageRejected?.[i]||0):running&&i===stage?phase+' · '+n+' шар':'Нет завершённого измерения';stages.append(label,value)}\n $('hunterstart').disabled=hunterCommandBusy||!cfgReady||!d.taskOk||running;$('hunterstop').disabled=hunterCommandBusy||!running;\n let note='Оценка по принятой сложности шар. Приблизительный интервал учитывает случайность шар и разброс двух повторов; это не гарантия прироста. Победитель автоматически не применяется.';\n if(t.state===2){\n  const eligible=[1,2].filter(i=>(t.repeatsCompleted?.[0]||0)>=2&&(t.repeatsCompleted?.[i]||0)>=2&&t.accepted?.[0]>=200&&t.accepted?.[i]>=200&&Number.isFinite(t.ci95Low?.[i])&&Number.isFinite(t.ci95High?.[0])&&t.ci95Low[i]>t.ci95High[0]&&t.rejected[i]/(t.accepted[i]+t.rejected[i])<=t.rejected[0]/(t.accepted[0]+t.rejected[0])+.005).sort((a,b)=>t.rates[b]-t.rates[a]);\n  note=(eligible.length?'Для отдельной повторной проверки: '+steps[eligible[0]]+' мс. ':'Преимущество относительно 500 мс не подтверждено. ')+note;\n }\n put('hunterconfidence',note);\n}\nlet guardianData=null,guardianBusy=false,guardianPoll=0,guardianCommandBusy=false;\nfunction guardianRender(){const d=guardianData,button=$('guardianenable');button.disabled=!d||d.taskOk===false||guardianBusy||guardianCommandBusy||!cfgReady;button.textContent=d?.enabled?'Внешняя проверка: вкл.':'Разрешить внешнюю проверку';if(!d){$('guardianstatus').textContent='Контроллер проверки сети недоступен.';$('guardianhash').textContent='';return}\n const errors={offline:'нет подключения',time_unsynced:'часы ещё не синхронизированы',tls_http:'сбой HTTPS или ответ сервиса',no_memory:'недостаточно памяти',invalid_response:'неверный ответ сервиса',incomplete_response:'неполный ответ сервиса',expired:'срок наблюдения завершён'};const state=['Кандидатов для проверки нет.','Ожидаем ответ внешнего сервиса.','Хеш пока не найден сервисом; это не доказательство потери блока.','Блок наблюдается внешним сервисом.','Ошибка проверки: '+(errors[d.error]||d.error||'нет ответа'),'Внешняя проверка выключена.'][d.state]||'Статус неизвестен.';\n $('guardianstatus').textContent=state+(d.state===3?(d.inBestChain===true?' Наблюдается в основной цепочке.':d.inBestChain===false?' Сейчас вне основной цепочки.':' Принадлежность основной цепочке не определена.'):'')+(Number.isFinite(d.height)&&d.height>0?' Высота '+d.height+'.':'')+(d.checked>0?' Проверено '+new Date(d.checked*1000).toLocaleString('ru-RU')+'.':'');\n $('guardianhash').textContent=d.hash?'Проверяемый хеш: '+d.hash:'';\n}\nasync function guardianRefresh(force=false){if(guardianBusy||(!force&&Date.now()-guardianPoll<15000))return;guardianBusy=true;guardianPoll=Date.now();try{const d=await readJson('/api/guardian');if(typeof d.enabled!=='boolean'||!Number.isInteger(d.state))throw Error('bad guardian');guardianData=d}catch(e){guardianData=null}finally{guardianBusy=false;guardianRender()}}\nasync function guardianToggle(){if(!guardianData||guardianBusy||guardianCommandBusy||!cfgReady)return;const enabled=!guardianData.enabled;if(enabled&&!confirm('Разрешить запрос хеша кандидата к mempool.space по HTTPS? Сервис увидит ваш внешний IP и хеш. Кошелёк и настройки пула не отправляются. Проверка не подтверждает выплату.'))return;guardianCommandBusy=true;guardianRender();try{const r=await fetch('/api/guardian',{method:'POST',body:JSON.stringify({enabled})});if(!r.ok)throw Error(await r.text());await guardianRefresh(true)}catch(e){toast('Не удалось изменить проверку сети: '+e.message)}finally{guardianCommandBusy=false;guardianRender()}}\n\nasync function hunterRefresh(force=false){if(hunterBusy||(!force&&Date.now()-hunterPoll<15000))return;hunterBusy=true;hunterPoll=Date.now();try{const d=await readJson('/api/hunter');if(!d.native||!Array.isArray(d.pools))throw Error('bad hunter');hunterData=d;hunterRender()}catch(e){hunterData=null;hunterRender()}finally{hunterBusy=false}}\nasync function hunterCommand(start){if(hunterCommandBusy||!hunterData)return;if(start&&!confirm('Запустить шесть этапов Benchmark Lab примерно на 3,5 часа? Каждый этап включает прогрев и измерение, каждый интервал проверяется дважды. При нестабильности тест прекращается. Исходный интервал возвращается; частота, напряжение и пулы не меняются. Результаты требуют повторной проверки.'))return;hunterCommandBusy=true;hunterRender();try{const r=await fetch('/api/hunter',{method:'POST',body:JSON.stringify({start})});if(!r.ok)throw Error(await r.text());toast(start?'Тест запущен':'Тест остановлен');await hunterRefresh(true)}catch(e){toast('Не удалось: '+e.message)}finally{hunterCommandBusy=false;hunterRender()}}\n"
